//! OIDC end-to-end tests (phase 5): a mock provider (a real TLS server on 127.0.0.1, self-signed certificate
//! generated by openssl, served by a small HTTP/1.1 loop) and the whole web flow through the real router:
//! `GET /login/oidc` → the provider's authorization URL, `GET /login/oidc/callback` → the back channel
//! (discovery + token exchange against the mock), the `id_token` checks, the account lookup, the session.
//! The transport is `Net::Direct` (no Capsicum in tests); the Casper channel is `fs::casper`'s own tests.

use crate::auth::{self, oidc, oidc_net};
use crate::config::{OidcRuntime, SecondFactor};
use crate::http::Settings;
use crate::http::tests::{A, Env, call, status};
use crate::tenant::tests::two_tenants_with;
use axum::http::{HeaderMap, StatusCode, header};
use base64ct::Encoding;
use rustls_pki_types::pem::PemObject;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// Percent-decodes one `k=v` pair of a query/form.
fn pair_value(kv: &str, k: &str) -> Option<String> {
    let (a, b) = kv.split_once('=')?;
    if a != k {
        return None;
    }
    percent_encoding::percent_decode_str(b)
        .decode_utf8()
        .ok()
        .map(|c| c.into_owned())
}

// ---------------------------------------------------------------- the mock provider

/// The client secret, with the characters a Basic header must form-encode (RFC 6749 §2.3.1): every full flow
/// proves the encoding, `client_secret_basic` and `client_secret_post` alike.
const SECRET: &str = "test:secret%2B+&=";

struct Mock {
    /// `state` → (nonce, code_challenge) seen at the authorization endpoint.
    flows: Mutex<HashMap<String, (String, String)>>,
    /// `amr` claims of the next `id_token`.
    amr: Mutex<Vec<String>>,
    /// `sub` of the next `id_token`.
    sub: Mutex<String>,
    /// When set, the token endpoint answers an error with this code.
    token_error: Mutex<Option<String>>,
    /// When set, the `id_token`'s nonce is this instead of the flow's.
    bad_nonce: Mutex<bool>,
    /// How the discovery endpoint answers: 0 = the document, 1 = status 500, 2 = not JSON, 3 = over the size cap,
    /// 4 = exactly at the size cap.
    discovery_mode: Mutex<u8>,
    /// The authorization code the token endpoint accepts (a test can hand it a long one).
    code: Mutex<String>,
    /// The `Host` header of the last request: the authority must carry the port (`host:port`, never `host` alone).
    host_header: Mutex<String>,
    /// Advertise only `client_secret_post` (the token endpoint then wants the secret in the form, no header).
    auth_post: Mutex<bool>,
    /// Advertise `authorization_response_iss_parameter_supported` (RFC 9207: the callback must then require `iss`).
    iss_param: Mutex<bool>,
    issuer: String,
    client_id: String,
    secret: String,
}

fn b64(b: &[u8]) -> String {
    base64ct::Base64UrlUnpadded::encode_string(b)
}

fn id_token(issuer: &str, aud: &str, nonce: &str, sub: &str, amr: &[String], now: i64) -> String {
    let amr_json = format!(
        "[{}]",
        amr.iter().map(|a| format!("\"{a}\"")).collect::<Vec<_>>().join(",")
    );
    let claims = format!(
        r#"{{"iss":"{issuer}","aud":"{aud}","exp":{},"iat":{},"nonce":"{nonce}","sub":"{sub}","amr":{amr_json}}}"#,
        now + 300,
        now
    );
    format!(
        "{}.{}.{}",
        b64(br#"{"alg":"RS256","typ":"JWT"}"#),
        b64(claims.as_bytes()),
        b64(b"sig")
    )
}

/// Serves one HTTP/1.1 request on a TLS stream, answers, closes.
async fn serve_one(mut tls: tokio_rustls::server::TlsStream<tokio::net::TcpStream>, m: Arc<Mock>) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let mut buf = Vec::new();
    let mut tmp = [0u8; 8192];
    let head_end = loop {
        if let Some(p) = find(&buf, b"\r\n\r\n") {
            break p + 4;
        }
        match tls.read(&mut tmp).await {
            Ok(0) | Err(_) => return,
            Ok(n) => buf.extend_from_slice(&tmp[..n]),
        }
    };
    let head = String::from_utf8_lossy(&buf[..head_end]).to_string();
    let mut lines = head.lines();
    let req = lines.next().unwrap_or("").to_string();
    let mut headers: HashMap<String, String> = HashMap::new();
    let mut len = 0usize;
    for l in lines {
        if let Some((k, v)) = l.split_once(':') {
            let k = k.trim().to_ascii_lowercase();
            let v = v.trim().to_string();
            if k == "content-length" {
                len = v.parse().unwrap_or(0);
            }
            headers.insert(k, v);
        }
    }
    while buf.len() < head_end + len {
        match tls.read(&mut tmp).await {
            Ok(0) | Err(_) => return,
            Ok(n) => buf.extend_from_slice(&tmp[..n]),
        }
    }
    *m.host_header.lock().unwrap() = headers.get("host").cloned().unwrap_or_default();
    let body = String::from_utf8_lossy(&buf[head_end..head_end + len]).to_string();
    let mut parts = req.split(' ');
    let method = parts.next().unwrap_or("").to_string();
    let target = parts.next().unwrap_or("").to_string();
    let path = target.split('?').next().unwrap_or("").to_string();
    let query = |k: &str| -> Option<String> { target.split_once('?')?.1.split('&').find_map(|kv| pair_value(kv, k)) };
    let form = |k: &str| body.split('&').find_map(|kv| pair_value(kv, k));
    let (code, text, ctype) = match (method.as_str(), path.as_str()) {
        ("GET", "/.well-known/openid-configuration") => match *m.discovery_mode.lock().unwrap() {
            1 => ("500", r#"{"error":"boom"}"#.to_string(), "application/json"),
            2 => ("200", "this is not json".to_string(), "application/json"),
            3 => (
                "200",
                format!("{{\"issuer\":\"{}\"}}", m.issuer) + &" ".repeat(oidc::MAX_PROVIDER_JSON_BYTES),
                "application/json",
            ),
            4 => {
                // A valid document of exactly the cap: the bound itself is accepted.
                let doc = format!(
                    r#"{{"issuer":"{}","authorization_endpoint":"{}/authorize","token_endpoint":"{}/token","response_types_supported":["code"],"code_challenge_methods_supported":["S256"],"token_endpoint_auth_methods_supported":["client_secret_basic"]}}"#,
                    m.issuer, m.issuer, m.issuer
                );
                let pad = oidc::MAX_PROVIDER_JSON_BYTES - doc.len();
                ("200", format!("{doc}{}", " ".repeat(pad)), "application/json")
            }
            _ => {
                let auths = if *m.auth_post.lock().unwrap() {
                    r#"["client_secret_post"]"#
                } else {
                    r#"["client_secret_basic"]"#
                };
                let iss_param = if *m.iss_param.lock().unwrap() { "true" } else { "false" };
                (
                    "200",
                    format!(
                        r#"{{"issuer":"{}","authorization_endpoint":"{}/authorize","token_endpoint":"{}/token","response_types_supported":["code"],"code_challenge_methods_supported":["S256"],"token_endpoint_auth_methods_supported":{},"authorization_response_iss_parameter_supported":{}}}"#,
                        m.issuer, m.issuer, m.issuer, auths, iss_param
                    ),
                    "application/json",
                )
            }
        },
        ("GET", "/authorize") => {
            let state = query("state").unwrap_or_default();
            let nonce = query("nonce").unwrap_or_default();
            let challenge = query("code_challenge").unwrap_or_default();
            let redirect = query("redirect_uri").unwrap_or_default();
            m.flows.lock().unwrap().insert(state.clone(), (nonce, challenge));
            let loc = format!("{redirect}?code=test-code&state={state}");
            ("303", format!("Location: {loc}\r\n"), "text/plain")
        }
        ("POST", "/token") => {
            // Client authentication: Basic client_id:secret by default, the secret in the form with `post`.
            // Two clients exist (alpha's and beta's, the cross-tenant test): the `aud` follows the one used.
            let basic = headers
                .get("authorization")
                .filter(|a| a.starts_with("Basic "))
                .and_then(|a| base64ct::Base64::decode_vec(&a["Basic ".len()..]).ok())
                .and_then(|b| String::from_utf8(b).ok())
                .and_then(|b| b.split_once(':').map(|(u, p)| (u.to_string(), p.to_string())))
                // RFC 6749 §2.3.1: the provider form-decodes both values, as Authelia does.
                .and_then(|(u, p)| Some((pair_value(&format!("u={u}"), "u")?, pair_value(&format!("p={p}"), "p")?)));
            let (client, auth_ok) = if *m.auth_post.lock().unwrap() {
                let client = form("client_id").unwrap_or_default();
                let ok = !headers.contains_key("authorization")
                    && form("client_secret").as_deref() == Some(m.secret.as_str());
                (client, ok)
            } else {
                match basic {
                    Some((u, p)) if p == m.secret => (u, true),
                    _ => (String::new(), false),
                }
            };
            if !auth_ok || (client != m.client_id && client != "beastbox-beta") {
                ("400", r#"{"error":"invalid_client"}"#.to_string(), "application/json")
            } else if let Some(e) = m.token_error.lock().unwrap().clone() {
                ("400", format!(r#"{{"error":"{e}"}}"#), "application/json")
            } else {
                let code = form("code").unwrap_or_default();
                let verifier = form("code_verifier").unwrap_or_default();
                let redirect = form("redirect_uri").unwrap_or_default();
                let want = m.code.lock().unwrap().clone();
                let ok = code == want
                    && [
                        "https://files.alpha.example/login/oidc/callback",
                        "https://x.beta.example/login/oidc/callback",
                    ]
                    .contains(&redirect.as_str());
                // PKCE: find the flow whose challenge matches S256(verifier).
                use sha2::Digest;
                let challenge = b64(&sha2::Sha256::digest(verifier.as_bytes()));
                let found = m
                    .flows
                    .lock()
                    .unwrap()
                    .iter()
                    .find(|(_, (_, ch))| *ch == challenge)
                    .map(|(_, (nonce, _))| nonce.clone());
                match found.filter(|_| ok) {
                    None => ("400", r#"{"error":"invalid_grant"}"#.to_string(), "application/json"),
                    Some(nonce) => {
                        let nonce = if *m.bad_nonce.lock().unwrap() {
                            "wrong".to_string()
                        } else {
                            nonce
                        };
                        let sub = m.sub.lock().unwrap().clone();
                        let amr = m.amr.lock().unwrap().clone();
                        let tok = id_token(&m.issuer, &client, &nonce, &sub, &amr, crate::db::now_secs());
                        ("200", format!(r#"{{"id_token":"{tok}"}}"#), "application/json")
                    }
                }
            }
        }
        _ => ("404", r#"{"error":"not_found"}"#.to_string(), "application/json"),
    };
    let resp = if code == "303" {
        format!("HTTP/1.1 303 See Other\r\n{text}content-length: 0\r\nconnection: close\r\n\r\n")
    } else {
        format!(
            "HTTP/1.1 {code} X\r\ncontent-type: {ctype}\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{text}",
            text.len()
        )
    };
    let _ = tls.write_all(resp.as_bytes()).await;
    let _ = tls.shutdown().await;
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

/// Starts the mock provider on 127.0.0.1:0 with a fresh test CA and a leaf certificate for `localhost`
/// (openssl). Returns (port, CA file path, mock state).
async fn spawn_mock(dir: &std::path::Path, amr: Vec<String>) -> (u16, std::path::PathBuf, Arc<Mock>) {
    let ca = dir.join("ca.pem");
    let ca_key = dir.join("ca-key.pem");
    let cert = dir.join("cert.pem");
    let key = dir.join("key.pem");
    let csr = dir.join("csr.pem");
    let ext = dir.join("ext.cnf");
    std::fs::write(
        &ext,
        "subjectAltName=DNS:localhost,IP:127.0.0.1\nbasicConstraints=critical,CA:FALSE\n",
    )
    .unwrap();
    let run = |args: &[&str]| {
        let s = std::process::Command::new("openssl").args(args).output().unwrap();
        assert!(
            s.status.success(),
            "openssl {args:?}: {}",
            String::from_utf8_lossy(&s.stderr)
        );
    };
    run(&[
        "req",
        "-x509",
        "-newkey",
        "rsa:2048",
        "-nodes",
        "-keyout",
        ca_key.to_str().unwrap(),
        "-out",
        ca.to_str().unwrap(),
        "-days",
        "3650",
        "-subj",
        "/CN=Beastbox test CA",
        "-addext",
        "basicConstraints=critical,CA:TRUE",
        "-addext",
        "keyUsage=critical,keyCertSign,cRLSign",
    ]);
    run(&[
        "req",
        "-newkey",
        "rsa:2048",
        "-nodes",
        "-keyout",
        key.to_str().unwrap(),
        "-out",
        csr.to_str().unwrap(),
        "-subj",
        "/CN=localhost",
    ]);
    run(&[
        "x509",
        "-req",
        "-in",
        csr.to_str().unwrap(),
        "-CA",
        ca.to_str().unwrap(),
        "-CAkey",
        ca_key.to_str().unwrap(),
        "-CAcreateserial",
        "-out",
        cert.to_str().unwrap(),
        "-days",
        "3650",
        "-extfile",
        ext.to_str().unwrap(),
    ]);
    let mut certs: Vec<rustls_pki_types::CertificateDer<'static>> =
        rustls_pki_types::CertificateDer::pem_slice_iter(&std::fs::read(&cert).unwrap())
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
    // The chain: leaf + CA.
    certs.extend(
        rustls_pki_types::CertificateDer::pem_slice_iter(&std::fs::read(&ca).unwrap())
            .collect::<Result<Vec<_>, _>>()
            .unwrap(),
    );
    let key = rustls_pki_types::PrivateKeyDer::from_pem_file(&key).unwrap();
    let config = rustls::ServerConfig::builder()
        .with_no_client_auth()
        .with_single_cert(certs, key)
        .unwrap();
    let acceptor = tokio_rustls::TlsAcceptor::from(Arc::new(config));
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let issuer = format!("https://localhost:{port}");
    let m = Arc::new(Mock {
        flows: Mutex::new(HashMap::new()),
        amr: Mutex::new(amr),
        sub: Mutex::new("sub-bob".to_string()),
        token_error: Mutex::new(None),
        bad_nonce: Mutex::new(false),
        discovery_mode: Mutex::new(0),
        code: Mutex::new("test-code".to_string()),
        host_header: Mutex::new(String::new()),
        auth_post: Mutex::new(false),
        iss_param: Mutex::new(false),
        client_id: "beastbox-alpha".to_string(),
        secret: SECRET.to_string(),
        issuer: issuer.clone(),
    });
    let m2 = m.clone();
    tokio::spawn(async move {
        while let Ok((tcp, _)) = listener.accept().await {
            let a = acceptor.clone();
            let m = m2.clone();
            tokio::spawn(async move {
                if let Ok(tls) = a.accept(tcp).await {
                    serve_one(tls, m).await;
                }
            });
        }
    });
    (port, ca, m)
}

