fn oidc_runtime(port: u16, ca: &std::path::Path, sf: SecondFactor, amr: Vec<String>) -> OidcRuntime {
    OidcRuntime {
        client: oidc::OidcClient::new(&format!("https://localhost:{port}"), "beastbox-alpha", &[]).unwrap(),
        secret: SECRET.to_string(),
        second_factor: sf,
        required_amr: amr,
        connect_addr: Some(format!("127.0.0.1:{port}").parse().unwrap()),
        tls: std::sync::Arc::new(oidc_net::tls_config(ca).unwrap()),
        base: "https://files.alpha.example".to_string(),
        password_login: false,
        discovery: Mutex::new(None),
    }
}

/// A runtime that never reaches the network: the login-page tests only look at the form and the POST.
fn oidc_offline(password_login: bool) -> OidcRuntime {
    OidcRuntime {
        client: oidc::OidcClient::new("https://auth.example", "beastbox-alpha", &[]).unwrap(),
        secret: SECRET.to_string(),
        second_factor: SecondFactor::Beastbox,
        required_amr: vec![],
        connect_addr: None,
        tls: oidc_net::test_tls(),
        base: "https://files.alpha.example".to_string(),
        password_login,
        discovery: Mutex::new(None),
    }
}

/// An `Env` whose alpha tenant has the given OIDC client, with `bob` bound to `sub-bob`; also returns alpha's
/// `TenantCtx` (to forge a flow cookie or touch the db in tests).
fn env_oidc(o: OidcRuntime) -> (Env, crate::tenant::TenantCtx) {
    env_oidc_with(o, None)
}

/// Same, with an OIDC client on beta too (the cross-tenant tests).
fn env_oidc_with(o: OidcRuntime, beta: Option<OidcRuntime>) -> (Env, crate::tenant::TenantCtx) {
    env_oidc_settings(o, beta, Settings::default())
}

/// Same, with the given server settings (a tenant's `two_factor`).
fn env_oidc_settings(o: OidcRuntime, beta: Option<OidcRuntime>, settings: Settings) -> (Env, crate::tenant::TenantCtx) {
    let (reg, a, b) = two_tenants_with(Some(o), beta);
    for d in [a.path(), b.path()] {
        std::fs::create_dir(d.join("alice")).unwrap();
        crate::fs::Root::open_dir(&d.join("alice"))
            .unwrap()
            .ensure_layout()
            .unwrap();
    }
    std::fs::create_dir(a.path().join("bob")).unwrap();
    crate::fs::Root::open_dir(&a.path().join("bob"))
        .unwrap()
        .ensure_layout()
        .unwrap();
    let dbd = tempfile::tempdir().unwrap();
    let db = auth::tests::db_with_users(&reg, dbd.path());
    let alpha = reg.by_name("alpha").unwrap();
    let issuer = alpha.oidc().unwrap().client.issuer.raw.clone();
    db.user_add_oidc(&alpha, "bob", false).unwrap();
    db.user_oidc_link(&alpha, "bob", &issuer, "sub-bob").unwrap();
    for t in reg.all() {
        t.journal().open(&dbd.path().join(format!("{}.log", t.name()))).unwrap();
    }
    let state = Arc::new(crate::http::App::new(reg, db, settings).unwrap());
    let env = Env {
        app: crate::http::router(state.clone()),
        state,
        a_root: a,
        _b_root: b,
        _db: dbd,
    };
    (env, alpha)
}

/// Query parameters of a URL, percent-decoded.
fn qs(url: &str) -> HashMap<String, String> {
    url.split_once('?')
        .map(|(_, q)| {
            q.split('&')
                .filter_map(|kv| {
                    let (k, _) = kv.split_once('=')?;
                    Some((k.to_string(), pair_value(kv, k)?))
                })
                .collect()
        })
        .unwrap_or_default()
}

/// The `name=value` pair of a `Set-Cookie` header.
fn cookie_pair(h: &HeaderMap, name: &str) -> Option<String> {
    h.get_all(header::SET_COOKIE)
        .iter()
        .filter_map(|v| v.to_str().ok())
        .find_map(|c| {
            let pair = c.split(';').next()?;
            let (k, _) = pair.split_once('=')?;
            (k == name).then(|| pair.to_string())
        })
}

/// The flow cookie name in tests (`insecure_cookies` is off in `Settings::default`).
fn flow_cookie_name(e: &Env) -> String {
    crate::web::cookie_name(&e.state, "oidc")
}

struct Start {
    location: String,
    flow: String,
}

/// A GET against the mock provider (TLS), as the browser would do: returns (status, location header).
async fn mock_get(ca: &std::path::Path, url: &str) -> (u16, Option<String>) {
    let rest = url.strip_prefix("https://").unwrap();
    let (hostport, path) = rest
        .split_once('/')
        .map(|(h, p)| (h, format!("/{p}")))
        .unwrap_or((rest, "/".into()));
    let (host, port) = hostport.split_once(':').unwrap();
    let port: u16 = port.parse().unwrap();
    let tcp = tokio::net::TcpStream::connect((host, port)).await.unwrap();
    let cfg = crate::auth::oidc_net::tls_config(ca).unwrap();
    let name = rustls_pki_types::ServerName::try_from(host.to_string()).unwrap();
    let mut tls = tokio_rustls::TlsConnector::from(Arc::new(cfg))
        .connect(name, tcp)
        .await
        .unwrap();
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    tls.write_all(format!("GET {path} HTTP/1.1\r\nhost: {hostport}\r\nconnection: close\r\n\r\n").as_bytes())
        .await
        .unwrap();
    let mut buf = Vec::new();
    tls.read_to_end(&mut buf).await.unwrap();
    let head = String::from_utf8_lossy(&buf).to_string();
    let status: u16 = head.split(' ').nth(1).unwrap().parse().unwrap();
    let loc = head.lines().find_map(|l| {
        l.split_once(':')
            .filter(|(k, _)| k.eq_ignore_ascii_case("location"))
            .map(|(_, v)| v.trim().to_string())
    });
    (status, loc)
}

/// `GET /login/oidc` on alpha: returns the authorization URL and the flow cookie.
async fn start(e: &Env, next: &str) -> (StatusCode, HeaderMap, Start) {
    let path = if next.is_empty() {
        "/login/oidc".to_string()
    } else {
        format!("/login/oidc?next={next}")
    };
    let (s, h, body) = call(&e.app, "GET", &path, &[A], "").await;
    assert_eq!(s, StatusCode::SEE_OTHER, "GET {path} -> {s}: {:.300}", body);
    let loc = h["location"].to_str().unwrap().to_string();
    let flow = cookie_pair(&h, &flow_cookie_name(e)).expect("flow cookie");
    (s, h, Start { location: loc, flow })
}

/// Drives the provider side: reads `state`/`nonce`/`code_challenge` from the authorization URL, and the
/// browser follows the authorization URL (the mock records the flow and redirects to the callback).
async fn authorize(ca: &std::path::Path, start: &Start) -> HashMap<String, String> {
    let (status, loc) = mock_get(ca, &start.location).await;
    assert_eq!(status, 303, "authorize -> {status}");
    let loc = loc.expect("no Location from authorize");
    assert!(
        loc.starts_with("https://files.alpha.example/login/oidc/callback?code=test-code&state="),
        "{loc}"
    );
    qs(&start.location)
}

/// `GET /login/oidc/callback` with the flow cookie and the given query.
async fn callback(e: &Env, flow: &str, query: &str) -> (StatusCode, HeaderMap, String) {
    call(
        &e.app,
        "GET",
        &format!("/login/oidc/callback?{query}"),
        &[A, ("cookie", flow)],
        "",
    )
    .await
}

/// The session cookie of a successful callback, if any.
fn sess_cookie(e: &Env, h: &HeaderMap) -> Option<String> {
    cookie_pair(h, &crate::web::cookie_name(&e.state, "sess"))
}

