/// Full flow: start → the provider's authorization URL → callback → session → the files page. With
/// `next=/web/account` the redirect goes there. The mock checks Basic auth, the redirect_uri and PKCE.
#[tokio::test]
async fn oidc_full_flow_and_next() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m_host) = spawn_mock(d.path(), vec!["pwd".into()]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec!["mfa".into()]);
    let (e, _alpha) = env_oidc(o);
    // The login page shows the SSO button on alpha, not on beta.
    let (_, _, body) = call(&e.app, "GET", "/login", &[A], "").await;
    assert!(body.contains("/login/oidc"), "no SSO button on alpha's login page");
    let (_, _, body) = call(&e.app, "GET", "/login", &[("host", "x.beta.example")], "").await;
    assert!(!body.contains("/login/oidc"), "SSO button on beta (no [tenant.oidc])");
    // Without OIDC, the routes 404.
    assert_eq!(
        status(&e.app, "GET", "/login/oidc", &[("host", "x.beta.example")]).await,
        StatusCode::NOT_FOUND
    );

    // Start with next=/web/account.
    let (s, _h, st) = start(&e, "/web/account").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    let p = authorize(&ca, &st).await;
    assert!(
        st.location.starts_with(&format!("https://localhost:{port}/authorize?")),
        "{}",
        st.location
    );
    assert_eq!(p["response_type"], "code");
    assert_eq!(p["client_id"], "beastbox-alpha");
    assert_eq!(p["redirect_uri"], "https://files.alpha.example/login/oidc/callback");
    assert_eq!(p["code_challenge_method"], "S256");
    assert!(p.contains_key("state") && p.contains_key("nonce") && p.contains_key("code_challenge"));

    // The provider echoes state, the callback accepts it and opens a session.
    let q = format!("code=test-code&state={}", p["state"]);
    let (s, h, _) = callback(&e, &st.flow, &q).await;
    assert_eq!(s, StatusCode::SEE_OTHER, "callback refused");
    assert_eq!(h["location"].to_str().unwrap(), "/web/account");
    let sess = sess_cookie(&e, &h).expect("no session cookie");
    // The flow cookie is cleared.
    assert!(h.get_all(header::SET_COOKIE).iter().any(|v| {
        v.to_str().unwrap().starts_with(&format!("{}=", flow_cookie_name(&e)))
            && v.to_str().unwrap().contains("Max-Age=0")
    }));
    // The session opens the app.
    let (s, _, body) = call(&e.app, "GET", "/web/account", &[A, ("cookie", sess.as_str())], "").await;
    assert_eq!(s, StatusCode::OK);
    assert!(body.contains("bob"), "the session is not bob's: {body:.200}");

    // The authority carried the port, as a direct HTTP/1.1 server expects (`host:port`, not `host`).
    assert_eq!(
        *m_host.host_header.lock().unwrap(),
        format!("localhost:{port}"),
        "the Host header must keep the port"
    );
    // Default next: the files page.
    let (s, _h, st) = start(&e, "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    let p = authorize(&ca, &st).await;
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(h["location"].to_str().unwrap(), "/web/files/");
}

/// Refusals: bad state, unknown account, provider error, bad nonce, missing amr — each redirects to
/// `/login` without a session, and counts in the login's rate limit (the 11th failure is a 429).
#[tokio::test]
async fn oidc_refusals_and_rate_limit() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec!["mfa".into()]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Provider, vec!["mfa".into()]);
    let (e, _alpha) = env_oidc(o);
    let (s, _h, st) = start(&e, "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    let p = authorize(&ca, &st).await;

    // Bad state.
    let (s, h, _) = callback(&e, &st.flow, "code=test-code&state=0000").await;
    assert_eq!((s, h["location"].to_str().unwrap()), (StatusCode::SEE_OTHER, "/login"));
    assert!(sess_cookie(&e, &h).is_none());
    // No flow cookie at all.
    let (s, h, _) = callback(&e, "", &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert!(sess_cookie(&e, &h).is_none());
    // Unknown account (sub not linked).
    *m.sub.lock().unwrap() = "sub-nobody".to_string();
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert!(sess_cookie(&e, &h).is_none());
    *m.sub.lock().unwrap() = "sub-bob".to_string();
    // Provider error at the token endpoint.
    *m.token_error.lock().unwrap() = Some("invalid_grant".into());
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let (_s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert!(sess_cookie(&e, &h).is_none());
    *m.token_error.lock().unwrap() = None;
    // Wrong nonce in the id_token.
    *m.bad_nonce.lock().unwrap() = true;
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let (_s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert!(sess_cookie(&e, &h).is_none());
    *m.bad_nonce.lock().unwrap() = false;
    // amr without a required method (second_factor = provider, required_amr = ["mfa"]).
    *m.amr.lock().unwrap() = vec!["pwd".into()];
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let (_s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert!(sess_cookie(&e, &h).is_none());
    // With the required amr: accepted.
    *m.amr.lock().unwrap() = vec!["pwd".into(), "mfa".into()];
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert!(sess_cookie(&e, &h).is_some(), "required amr present but refused");
    assert_eq!(h["location"].to_str().unwrap(), "/web/files/");

    // The refusals above were recorded: after enough of them the callback answers 429.
    let mut last = s;
    for _ in 0..12 {
        let (s, _h, _) = callback(&e, &st.flow, "code=test-code&state=0000").await;
        last = s;
    }
    assert_eq!(
        last,
        StatusCode::TOO_MANY_REQUESTS,
        "the login's rate limit must apply to the callback"
    );
}

/// A flow cookie of another tenant (beta has no OIDC, but the cookie is keyed by tenant): refused.
#[tokio::test]
async fn oidc_flow_cookie_is_bound_to_the_tenant() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec!["mfa".into()]);
    let (e, _alpha) = env_oidc(o);
    let (s, _h, st) = start(&e, "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    let p = authorize(&ca, &st).await;
    // Replay alpha's flow cookie on beta's host: beta has no OIDC → 404; the cookie would not validate anyway.
    let (s, _, _) = call(
        &e.app,
        "GET",
        &format!("/login/oidc/callback?code=test-code&state={}", p["state"]),
        &[("host", "x.beta.example"), ("cookie", st.flow.as_str())],
        "",
    )
    .await;
    assert_eq!(s, StatusCode::NOT_FOUND);
    // A tampered flow cookie on alpha: refused.
    let tampered = format!("{}x", st.flow.strip_suffix('x').unwrap_or(&st.flow));
    let (s, h, _) = callback(&e, &tampered, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(h["location"].to_str().unwrap(), "/login");
    assert!(sess_cookie(&e, &h).is_none());
}

// ---------------------------------------------------------------- failure paths of the back channel

/// A flow cookie minted directly (without calling `/login/oidc`), e.g. to reach the callback's own discovery.
fn forged_flow(e: &Env, alpha: &crate::tenant::TenantCtx, next: &str) -> (String, String) {
    let f = oidc::new_flow(alpha, next, crate::db::now_secs()).unwrap();
    (
        format!("{}={}", crate::web::cookie_name(&e.state, "oidc"), f.cookie),
        f.state,
    )
}

/// A broken discovery document (status 500, not JSON, over the size cap): both routes answer 503 + Retry-After,
/// never a redirect to the provider, and no flow cookie is set.
#[tokio::test]
async fn oidc_discovery_failures_answer_503() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec![]).await;
    for mode in [1u8, 2, 3] {
        *m.discovery_mode.lock().unwrap() = mode;
        let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
        let (e, alpha) = env_oidc(o);
        let (s, h, body) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
        assert_eq!(s, StatusCode::SERVICE_UNAVAILABLE, "mode {mode}: {s} {body:.200}");
        assert_eq!(h[header::RETRY_AFTER].to_str().unwrap(), "30");
        assert!(
            cookie_pair(&h, &flow_cookie_name(&e)).is_none(),
            "mode {mode}: a flow cookie was set"
        );
        // The callback reaches the same fetch with a valid flow cookie: 503 too.
        let (flow, state) = forged_flow(&e, &alpha, "");
        let (s, h, _b) = callback(&e, &flow, &format!("code=test-code&state={state}")).await;
        assert_eq!(s, StatusCode::SERVICE_UNAVAILABLE, "mode {mode}");
        assert_eq!(h[header::RETRY_AFTER].to_str().unwrap(), "30");
    }
    *m.discovery_mode.lock().unwrap() = 0;
}

/// A discovery document of exactly the size cap is read like a small one: the bound is the cap itself, and the
/// back channel does not refuse it before the parser (a body one byte over is mode 3, refused).
#[tokio::test]
async fn oidc_discovery_at_the_size_cap_is_read() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec![]).await;
    *m.discovery_mode.lock().unwrap() = 4;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    let (e, _alpha) = env_oidc(o);
    let (s, h, body) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
    assert_eq!(
        s,
        StatusCode::SEE_OTHER,
        "a document at the cap was refused: {s} {body:.200}"
    );
    assert!(h["location"].to_str().unwrap().contains("/authorize?"));
    *m.discovery_mode.lock().unwrap() = 0;
}

/// The back channel is unreachable (closed port) or not TLS (plain server): fail closed, 503, no cookie.
#[tokio::test]
async fn oidc_back_channel_failures_answer_503() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    // Port 1 is closed; no connect_addr, so localhost is resolved then refused.
    let mut o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    o.client = oidc::OidcClient::new("https://localhost:1", "beastbox-alpha", &[]).unwrap();
    o.connect_addr = None;
    let (e, _alpha) = env_oidc(o);
    let (s, h, body) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
    assert_eq!(s, StatusCode::SERVICE_UNAVAILABLE, "{s} {body:.200}");
    assert_eq!(h[header::RETRY_AFTER].to_str().unwrap(), "30");
    assert!(cookie_pair(&h, &flow_cookie_name(&e)).is_none());

    // A plain TCP server (no TLS): the handshake fails, fail closed.
    let lst = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let plain = lst.local_addr().unwrap().port();
    tokio::spawn(async move {
        while let Ok((s, _)) = lst.accept().await {
            drop(s);
        }
    });
    let mut o = oidc_runtime(plain, &ca, SecondFactor::Beastbox, vec![]);
    o.client = oidc::OidcClient::new(&format!("https://localhost:{plain}"), "beastbox-alpha", &[]).unwrap();
    let (e, _alpha) = env_oidc(o);
    let (s, _h, body) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
    assert_eq!(
        s,
        StatusCode::SERVICE_UNAVAILABLE,
        "a non-TLS endpoint must be refused: {s} {body:.200}"
    );
}

/// The authorization `code` is bounded and printable before any use: missing, empty, with a space, or too long
/// are all refused (redirect to `/login`, no session).
#[tokio::test]
async fn oidc_callback_refuses_a_malformed_code() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    let (e, _alpha) = env_oidc(o);
    for bad in ["", "code=", "code=%20", &format!("code={}", "a".repeat(513))] {
        let (_s, _h, st) = start(&e, "").await; // a new flow per attempt (a used flow is refused)
        let p = authorize(&ca, &st).await;
        let state = &p["state"];
        let q = if bad.is_empty() {
            format!("state={state}")
        } else {
            format!("state={state}&{bad}")
        };
        let (s, h, _) = callback(&e, &st.flow, &q).await;
        assert_eq!(
            (s, h["location"].to_str().unwrap()),
            (StatusCode::SEE_OTHER, "/login"),
            "code {bad:.40}"
        );
        assert!(sess_cookie(&e, &h).is_none());
    }
    // An over-long code is refused by our bound, even when the provider would take it: the provider below accepts
    // any code the test hands it, so a session here would mean the bound is not enforced.
    *m.code.lock().unwrap() = "c".repeat(513);
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let state = &p["state"];
    let (s, h, _) = callback(&e, &st.flow, &format!("code={}&state={state}", "c".repeat(513))).await;
    assert_eq!((s, h["location"].to_str().unwrap()), (StatusCode::SEE_OTHER, "/login"));
    assert!(sess_cookie(&e, &h).is_none(), "an over-long code was accepted");
    *m.code.lock().unwrap() = "test-code".to_string();
    // A well-formed code still completes the flow.
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let state = &p["state"];
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={state}")).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert!(sess_cookie(&e, &h).is_some());
}

/// RFC 9207: when the discovery document says the provider echoes `iss`, the callback requires it.
#[tokio::test]
async fn oidc_iss_parameter_when_the_provider_echoes_it() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec![]).await;
    *m.iss_param.lock().unwrap() = true;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    let (e, _alpha) = env_oidc(o);
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let state = &p["state"];
    let issuer = format!("https://localhost:{port}");
    // Missing `iss` → refused.
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={state}")).await;
    assert_eq!((s, h["location"].to_str().unwrap()), (StatusCode::SEE_OTHER, "/login"));
    assert!(sess_cookie(&e, &h).is_none());
    // Wrong `iss` → refused.
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let state = &p["state"];
    let (_s, h, _) = callback(
        &e,
        &st.flow,
        &format!("code=test-code&state={state}&iss=https://evil.example"),
    )
    .await;
    assert_eq!(h["location"].to_str().unwrap(), "/login");
    assert!(sess_cookie(&e, &h).is_none());
    // The right `iss` → the flow completes.
    let (_s, _h, st) = start(&e, "").await; // a new flow: one callback each (a used flow is refused)
    let p = authorize(&ca, &st).await;
    let state = &p["state"];
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={state}&iss={issuer}")).await;
    assert_eq!(
        s,
        StatusCode::SEE_OTHER,
        "the echoed iss is required but the right one was refused"
    );
    assert!(sess_cookie(&e, &h).is_some());
}

