/// With TOTP on the account, the provider's sign-in opens a **pending** session and sends the browser to the code
/// page (with the flow's `next`), exactly like the password login.
#[tokio::test]
async fn oidc_with_totp_defers_to_the_code_page() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    let (e, alpha) = env_oidc(o);
    e.state.db.totp_enable(&alpha, "bob", &[7; 32], 0, &[], None).unwrap();
    // next=/web/account: after the code, the browser goes there.
    let (_s, _h, st) = start(&e, "/web/account").await;
    let p = authorize(&ca, &st).await;
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(h["location"].to_str().unwrap(), "/login/code?next=/web/account");
    let pending = sess_cookie(&e, &h).expect("pending session cookie");
    // A pending session is not a full one: the files page still redirects to the code page.
    let (s, h, _) = call(&e.app, "GET", "/web/files/", &[A, ("cookie", pending.as_str())], "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(h["location"].to_str().unwrap(), "/login/code");
    // Default next: /login/code.
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(h["location"].to_str().unwrap(), "/login/code");
}

/// `second_factor = "provider"`: the provider did both halves, so an account that still has a Beastbox TOTP
/// secret is **not** asked for its code — the `amr` check is the second factor.
#[tokio::test]
async fn oidc_provider_second_factor_skips_the_totp_page() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec!["mfa".into()]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Provider, vec!["mfa".into()]);
    let (e, alpha) = env_oidc(o);
    e.state.db.totp_enable(&alpha, "bob", &[7; 32], 0, &[], None).unwrap();
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(h["location"].to_str().unwrap(), "/web/files/", "no code page expected");
    let full = sess_cookie(&e, &h).expect("session cookie");
    // A full session: the files page opens.
    let (s, _, _) = call(&e.app, "GET", "/web/files/", &[A, ("cookie", full.as_str())], "").await;
    assert_eq!(s, StatusCode::OK);
    // And the `amr` gate still holds: without `mfa`, no session at all.
    *m.amr.lock().unwrap() = vec!["pwd".into()];
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let (_s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert!(sess_cookie(&e, &h).is_none());
}

/// Two tenants with single sign-on, sharing an issuer: alpha's flow cookie replayed on beta is refused (the
/// cookie is keyed by the tenant), and beta's own flow signs its own account in — same issuer, same `sub`.
#[tokio::test]
async fn oidc_cross_tenant_flow_is_refused() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let alpha_o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    let mut beta_o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    beta_o.client = oidc::OidcClient::new(&format!("https://localhost:{port}"), "beastbox-beta", &[]).unwrap();
    beta_o.base = "https://x.beta.example".to_string();
    let (e, _alpha) = env_oidc_with(alpha_o, Some(beta_o));
    // The same provider identity, `sub-bob`, on an account of each tenant.
    let beta = e.state.registry.by_name("beta").unwrap();
    let issuer = beta.oidc().unwrap().client.issuer.raw.clone();
    e.state.db.user_oidc_link(&beta, "alice", &issuer, "sub-bob").unwrap();
    let beta_host = ("host", "x.beta.example");

    // A flow started on alpha, then its cookie and state replayed on beta.
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let (s, h, _) = call(
        &e.app,
        "GET",
        &format!("/login/oidc/callback?code=test-code&state={}", p["state"]),
        &[beta_host, ("cookie", st.flow.as_str())],
        "",
    )
    .await;
    assert_eq!((s, h["location"].to_str().unwrap()), (StatusCode::SEE_OTHER, "/login"));
    assert!(sess_cookie(&e, &h).is_none());

    // Beta's own flow: the same `sub` signs beta's `alice` in (the refusal above was the tenant binding).
    let (s, h, _) = call(&e.app, "GET", "/login/oidc", &[beta_host], "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    let loc = h["location"].to_str().unwrap().to_string();
    let beta_flow = cookie_pair(&h, &flow_cookie_name(&e)).expect("beta flow cookie");
    let (status, loc) = mock_get(&ca, &loc).await;
    assert_eq!(status, 303);
    let loc = loc.expect("no Location from authorize");
    assert!(loc.starts_with("https://x.beta.example/login/oidc/callback?"), "{loc}");
    let state = qs(&loc)["state"].clone();
    let (s, h, body) = call(
        &e.app,
        "GET",
        &format!("/login/oidc/callback?code=test-code&state={state}"),
        &[beta_host, ("cookie", beta_flow.as_str())],
        "",
    )
    .await;
    assert_eq!(s, StatusCode::SEE_OTHER, "beta's own flow refused: {body:.200}");
    assert_eq!(h["location"].to_str().unwrap(), "/web/files/");
    assert!(sess_cookie(&e, &h).is_some());
}

/// A tenant that delegates its sign-in to a provider takes the Beastbox password form away: the provider is the
/// only way in, and the POST is refused without touching argon2 or the failure counters.
#[tokio::test]
async fn oidc_tenant_takes_the_password_form_away() {
    let (e, _alpha) = env_oidc(oidc_offline(false));
    let (s, _, page) = call(&e.app, "GET", "/login", &[A], "").await;
    assert_eq!(s, StatusCode::OK);
    assert!(!page.contains("name=\"password\""), "{page}");
    assert!(page.contains("/login/oidc"), "{page}");
    let (s, h, page) = call(&e.app, "POST", "/login", &[A], "user=alice&password=pw-alice").await;
    assert_eq!(s, StatusCode::FORBIDDEN);
    assert!(page.contains("identity provider"), "{page}");
    assert!(h.get("set-cookie").is_none(), "no session from a refused door");
    // Beta has no provider: its form stays, and no single sign-on button appears.
    let (s, _, page) = call(&e.app, "GET", "/login", &[("host", "x.beta.example")], "").await;
    assert_eq!(s, StatusCode::OK);
    assert!(
        page.contains("name=\"password\"") && !page.contains("/login/oidc"),
        "{page}"
    );
}

/// `password_login = true` keeps the local form beside the provider (break-glass account).
#[tokio::test]
async fn oidc_tenant_may_keep_the_password_login() {
    let (e, _alpha) = env_oidc(oidc_offline(true));
    let (_, _, page) = call(&e.app, "GET", "/login", &[A], "").await;
    assert!(
        page.contains("name=\"password\"") && page.contains("/login/oidc"),
        "{page}"
    );
    let (s, h, _) = call(&e.app, "POST", "/login", &[A], "user=alice&password=pw-alice").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert!(h.get("set-cookie").is_some(), "the password did not open a session");
}

/// The rule of the sign-in, as a property: a tenant that delegates to a provider opens **no** web session through
/// the password form, whatever the credentials (the account's real password included), and counts no failure; a
/// tenant that keeps the form (`password_login = true`) answers a session or a refusal, never a 403.
#[test]
fn closed_tenant_opens_nothing() {
    use percent_encoding::{NON_ALPHANUMERIC, utf8_percent_encode};
    let enc = |v: &str| utf8_percent_encode(v, NON_ALPHANUMERIC).to_string();
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    let (closed, _) = env_oidc(oidc_offline(false));
    let (open, _) = env_oidc(oidc_offline(true));
    let mut runner = proptest::test_runner::TestRunner::new(proptest::test_runner::Config {
        cases: 24,
        ..Default::default()
    });
    runner
        .run(
            &(proptest::prelude::any::<String>(), proptest::prelude::any::<String>()),
            |(user, pw)| {
                let body = format!("user={}&password={}", enc(&user), enc(&pw));
                let (s, h, _) = rt.block_on(call(&closed.app, "POST", "/login", &[A], &body));
                proptest::prop_assert_eq!(s, StatusCode::FORBIDDEN, "user={:?}", user);
                proptest::prop_assert!(h.get("set-cookie").is_none());
                let (s, h, _) = rt.block_on(call(&open.app, "POST", "/login", &[A], &body));
                proptest::prop_assert_ne!(s, StatusCode::FORBIDDEN, "user={:?}", user);
                proptest::prop_assert_eq!(h.get("set-cookie").is_some(), s == StatusCode::SEE_OTHER);
                Ok(())
            },
        )
        .unwrap();
}

/// `second_factor = "provider"` on a tenant with `two_factor = required`: the provider's `amr` is the second factor,
/// so an account without a Beastbox TOTP opens the files page, not the TOTP setup. With `password_login = true` a
/// password session is possible, so the setup is required again.
#[tokio::test]
async fn oidc_provider_second_factor_on_a_required_tenant() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec!["mfa".into()]).await;
    for (password_login, gate) in [(false, None), (true, Some("/web/2fa-setup"))] {
        let mut o = oidc_runtime(port, &ca, SecondFactor::Provider, vec!["mfa".into()]);
        o.password_login = password_login;
        let settings = Settings {
            two_factor: vec![("alpha".into(), crate::config::TwoFactor::Required)],
            ..Settings::default()
        };
        let (e, _alpha) = env_oidc_settings(o, None, settings);
        let (_s, _h, st) = start(&e, "").await;
        let p = authorize(&ca, &st).await;
        let (s, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
        assert_eq!(s, StatusCode::SEE_OTHER);
        let sess = sess_cookie(&e, &h).expect("session cookie");
        let (s, h, _) = call(&e.app, "GET", "/web/files/", &[A, ("cookie", sess.as_str())], "").await;
        match gate {
            None => assert_eq!(s, StatusCode::OK, "password_login = {password_login}"),
            Some(g) => {
                assert_eq!(s, StatusCode::SEE_OTHER, "password_login = {password_login}");
                assert_eq!(h["location"].to_str().unwrap(), g);
            }
        }
    }
}

/// A tenant answers on several hosts, but the provider sends the browser back to the base host only: a flow started
/// elsewhere is first moved to the base host (with its `next`), before any flow cookie is set. On the base host
/// (port included or not) the flow starts at once.
#[tokio::test]
async fn oidc_start_moves_to_the_base_host() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let (e, _alpha) = env_oidc(oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]));
    let other = ("host", "other.alpha.example");
    let (s, h, _) = call(&e.app, "GET", "/login/oidc?next=/web/account", &[other], "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert_eq!(
        h["location"].to_str().unwrap(),
        "https://files.alpha.example/login/oidc?next=/web/account"
    );
    assert!(cookie_pair(&h, &flow_cookie_name(&e)).is_none());
    // A `next` outside the allowlist is dropped, not carried.
    let (_s, h, _) = call(&e.app, "GET", "/login/oidc?next=https://evil.example/", &[other], "").await;
    assert_eq!(
        h["location"].to_str().unwrap(),
        "https://files.alpha.example/login/oidc"
    );
    // The base host, with or without its port, in any case: the flow starts (provider URL and flow cookie).
    for host in ["files.alpha.example", "files.alpha.example:443", "FILES.alpha.example"] {
        let (s, h, _) = call(&e.app, "GET", "/login/oidc", &[("host", host)], "").await;
        assert_eq!(s, StatusCode::SEE_OTHER, "{host}");
        assert!(h["location"].to_str().unwrap().contains("/authorize?"), "{host}");
        assert!(cookie_pair(&h, &flow_cookie_name(&e)).is_some(), "{host}");
    }
}

/// A failed discovery is remembered: for `DISCOVERY_RETRY` the routes answer 503 without reaching the provider (an
/// anonymous request must not open a connection each time), then the next request fetches again.
#[tokio::test]
async fn oidc_discovery_failure_is_not_refetched_at_once() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, m) = spawn_mock(d.path(), vec![]).await;
    *m.discovery_mode.lock().unwrap() = 1;
    let (e, alpha) = env_oidc(oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]));
    let (s, _h, _) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
    assert_eq!(s, StatusCode::SERVICE_UNAVAILABLE);
    // The provider is back, but the failure is still fresh: 503, and the mock sees no new request.
    *m.discovery_mode.lock().unwrap() = 0;
    *m.host_header.lock().unwrap() = String::new();
    let (s, h, _) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
    assert_eq!(s, StatusCode::SERVICE_UNAVAILABLE);
    assert_eq!(h[header::RETRY_AFTER].to_str().unwrap(), "30");
    assert_eq!(*m.host_header.lock().unwrap(), "", "the provider was reached again");
    // Once the delay has passed (the failure moved 31 s back), the next sign-in fetches and starts.
    let o = alpha.oidc().unwrap();
    let past = std::time::Instant::now()
        .checked_sub(std::time::Duration::from_secs(31))
        .unwrap();
    *o.discovery.lock().unwrap() = Some(Err(past));
    let (s, _h, _) = call(&e.app, "GET", "/login/oidc", &[A], "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    assert!(!m.host_header.lock().unwrap().is_empty());
}

/// A missing or forged flow cookie or `state` counts against the sender's address only: many addresses sending
/// them never close the tenant's sign-in (the tenant-wide limit stays open).
#[tokio::test]
async fn oidc_forged_cookie_does_not_fill_the_tenant_limit() {
    let (e, alpha) = env_oidc(oidc_offline(false));
    for i in 0..150u32 {
        let ip = format!("192.0.2.{}", i % 250);
        let (s, h, _) = call(
            &e.app,
            "GET",
            "/login/oidc/callback?code=c&state=s",
            &[A, ("x-real-ip", ip.as_str())],
            "",
        )
        .await;
        assert_eq!(s, StatusCode::SEE_OTHER, "request {i}");
        assert_eq!(h["location"].to_str().unwrap(), "/login");
    }
    // Nothing closed for the others: a callback from a new address is refused as usual (to /login), never a 429.
    let fresh = [A, ("x-real-ip", "203.0.113.77")];
    let (s, _, _) = call(&e.app, "GET", "/login/oidc/callback?code=c&state=s", &fresh, "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    // A forged `state` with a valid cookie: same rule.
    let (flow, _state) = forged_flow(&e, &alpha, "");
    for i in 0..150u32 {
        let ip = format!("198.51.100.{}", i % 250);
        let (s, _h, _) = call(
            &e.app,
            "GET",
            "/login/oidc/callback?code=c&state=bad",
            &[A, ("x-real-ip", ip.as_str()), ("cookie", flow.as_str())],
            "",
        )
        .await;
        assert_eq!(s, StatusCode::SEE_OTHER, "request {i}");
    }
    // Nothing closed for the others: a callback from a new address is refused as usual (to /login), never a 429.
    let fresh = [A, ("x-real-ip", "203.0.113.77")];
    let (s, _, _) = call(&e.app, "GET", "/login/oidc/callback?code=c&state=s", &fresh, "").await;
    assert_eq!(s, StatusCode::SEE_OTHER);
}

/// A complete sign-in through the provider for bob (bound to `sub-bob`, no password): the session cookie and its CSRF.
async fn bob_signs_in(e: &Env, ca: &std::path::Path) -> (String, String) {
    let (_s, _h, st) = start(e, "").await;
    let p = authorize(ca, &st).await;
    let (s, h, _) = callback(e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    assert_eq!(s, StatusCode::SEE_OTHER);
    let cookie = sess_cookie(e, &h).expect("bob signed in");
    let alpha = e.state.registry.by_name("alpha").unwrap();
    let csrf = auth::csrf_token(&alpha, cookie.split_once('=').unwrap().1);
    (cookie, csrf)
}

/// A flow signs in once: its cookie and `state` replayed, even within its 10 minutes, are refused (no session),
/// before any back-channel call.
#[tokio::test]
async fn oidc_flow_is_single_use() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Provider, vec![]);
    let (e, _alpha) = env_oidc(o);
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let q = format!("code=test-code&state={}", p["state"]);
    let (s, h, _) = callback(&e, &st.flow, &q).await;
    assert!(s == StatusCode::SEE_OTHER && sess_cookie(&e, &h).is_some());
    for _ in 0..2 {
        let (s, h, _) = callback(&e, &st.flow, &q).await;
        assert_eq!((s, h["location"].to_str().unwrap()), (StatusCode::SEE_OTHER, "/login"));
        assert!(sess_cookie(&e, &h).is_none(), "a used flow signed in again");
    }
    // A new flow still works.
    let (_, _) = bob_signs_in(&e, &ca).await;
}

/// An account bound to single sign-on, without a password nor two-step verification: a new app password needs a recent
/// sign-in (`FRESH_SIGN_IN`); an older session is ended and sent to sign in again, nothing created.
#[tokio::test]
async fn sso_account_app_password_needs_a_recent_sign_in() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Provider, vec![]);
    let (e, alpha) = env_oidc(o);
    let (cookie, csrf) = bob_signs_in(&e, &ca).await;
    let c = [A, ("cookie", cookie.as_str())];
    let (_, _, page) = call(&e.app, "GET", "/web/account", &c, "").await;
    assert!(page.contains("You may be asked to sign in again first.") && !page.contains("id=\"tok-pw\""));
    let (s, _, _) = call(
        &e.app,
        "POST",
        "/web/account/tokens",
        &c,
        &format!("csrf={csrf}&label=x"),
    )
    .await;
    assert_eq!(s, StatusCode::OK);
    assert_eq!(e.state.db.token_list(&alpha, "bob").unwrap().len(), 1);
    // The sign-in grows old: sent to sign in again, the session ended, nothing created.
    e.state.db.exec_for_test(&format!(
        "UPDATE session SET created_at = created_at - {} WHERE user_id = 'bob';",
        crate::web::FRESH_SIGN_IN + 1
    ));
    let (s, h, _) = call(&e.app, "POST", "/web/account/qr", &c, &format!("csrf={csrf}")).await;
    assert_eq!(
        (s, h["location"].to_str().unwrap()),
        (StatusCode::SEE_OTHER, "/login?next=/web/account")
    );
    assert_eq!(e.state.db.token_list(&alpha, "bob").unwrap().len(), 1);
    assert_eq!(
        status(&e.app, "GET", "/web/account", &c).await,
        StatusCode::SEE_OTHER,
        "session ended"
    );
}

/// An account bound to single sign-on with Beastbox's two-step verification and no password: its code is the proof,
/// for a new app password and to manage two-step verification (no password asked, `SURFACE.md` known limit 5).
#[tokio::test]
async fn sso_account_with_totp_proves_with_its_code() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Beastbox, vec![]);
    let (e, alpha) = env_oidc(o);
    let recovery = auth::tests::enable_totp(&e.state.db, &alpha, "bob");
    // Provider, then the code page: a full session.
    let (_s, _h, st) = start(&e, "").await;
    let p = authorize(&ca, &st).await;
    let (_, h, _) = callback(&e, &st.flow, &format!("code=test-code&state={}", p["state"])).await;
    let pending = sess_cookie(&e, &h).unwrap();
    let pc = auth::csrf_token(&alpha, pending.split_once('=').unwrap().1);
    let body = format!("csrf={pc}&code={}", auth::tests::code_at(0));
    let (_, h, _) = call(&e.app, "POST", "/login/code", &[A, ("cookie", pending.as_str())], &body).await;
    let cookie = sess_cookie(&e, &h).expect("full session");
    let csrf = auth::csrf_token(&alpha, cookie.split_once('=').unwrap().1);
    let c = [A, ("cookie", cookie.as_str())];
    let (_, _, page) = call(&e.app, "GET", "/web/account", &c, "").await;
    assert!(
        page.contains("id=\"tok-code\"") && !page.contains("id=\"tf-pw\""),
        "proof fields of an SSO account with TOTP"
    );
    // App password: the code is required, a wrong one refused, the next one accepted.
    for extra in ["", "&code=000000"] {
        let (s, _, _) = call(
            &e.app,
            "POST",
            "/web/account/tokens",
            &c,
            &format!("csrf={csrf}&label=x{extra}"),
        )
        .await;
        assert_eq!(s, StatusCode::UNAUTHORIZED, "{extra}");
    }
    let body = format!("csrf={csrf}&label=x&code={}", auth::tests::code_at(1));
    assert_eq!(
        call(&e.app, "POST", "/web/account/tokens", &c, &body).await.0,
        StatusCode::OK
    );
    assert_eq!(e.state.db.token_list(&alpha, "bob").unwrap().len(), 1);
    // New recovery codes with a recovery code alone: no password asked of an account that has none.
    let body = format!("csrf={csrf}&op=codes&code={}", recovery[0]);
    let (s, _, page) = call(&e.app, "POST", "/web/account/2fa", &c, &body).await;
    assert!(
        s == StatusCode::OK && page.contains("the old ones no longer work"),
        "{s}"
    );
}

/// A Login Flow started for `e`: the confirmation page's path.
async fn new_login_flow(e: &Env) -> String {
    let (_, _, body) = call(
        &e.app,
        "POST",
        "/index.php/login/v2",
        &[A, ("x-forwarded-proto", "http")],
        "",
    )
    .await;
    let f = body
        .split("/index.php/login/v2/flow/")
        .nth(1)
        .unwrap()
        .split('"')
        .next()
        .unwrap();
    format!("/index.php/login/v2/flow/{f}")
}

/// Login Flow for an account bound to single sign-on: no password to ask; the code when it has two-step
/// verification, otherwise a recent sign-in — an older one is ended and sent to sign in again, back to the flow.
#[tokio::test]
async fn sso_account_login_flow_proof() {
    let d = tempfile::tempdir().unwrap();
    let (port, ca, _m) = spawn_mock(d.path(), vec![]).await;
    let o = oidc_runtime(port, &ca, SecondFactor::Provider, vec![]);
    let (e, alpha) = env_oidc(o);
    let (cookie, csrf) = bob_signs_in(&e, &ca).await;
    let c = [A, ("cookie", cookie.as_str())];
    let f = new_login_flow(&e).await;
    let (_, _, page) = call(&e.app, "GET", &f, &c, "").await;
    assert!(
        page.contains("Authorize this client")
            && page.contains(&format!("name=\"csrf\" value=\"{csrf}\""))
            && !page.contains("name=\"password\"")
            && !page.contains("name=\"code\"")
    );
    // AUTH-01: forged POST (missing/wrong CSRF or same-site/cross-site origin) never issues an app password.
    for body in ["", "csrf=wrong"] {
        assert_eq!(
            call(&e.app, "POST", &f, &c, body).await.0,
            StatusCode::FORBIDDEN,
            "{body}"
        );
    }
    for hdr in [
        ("sec-fetch-site", "same-site"),
        ("sec-fetch-site", "cross-site"),
        ("origin", "https://other.alpha.example"),
    ] {
        let h = [A, ("cookie", cookie.as_str()), hdr];
        assert_eq!(
            call(&e.app, "POST", &f, &h, &format!("csrf={csrf}")).await.0,
            StatusCode::FORBIDDEN,
            "{hdr:?}"
        );
    }
    assert!(e.state.db.token_list(&alpha, "bob").unwrap().is_empty());
    assert_eq!(
        call(&e.app, "POST", &f, &c, &format!("csrf={csrf}")).await.0,
        StatusCode::OK
    );
    assert_eq!(e.state.db.token_list(&alpha, "bob").unwrap().len(), 1);
    e.state.db.exec_for_test(&format!(
        "UPDATE session SET created_at = created_at - {} WHERE user_id = 'bob';",
        crate::web::FRESH_SIGN_IN + 1
    ));
    let g = new_login_flow(&e).await;
    // Forged POST without CSRF on a stale SSO session must not log bob out either.
    assert_eq!(call(&e.app, "POST", &g, &c, "").await.0, StatusCode::FORBIDDEN);
    assert_eq!(call(&e.app, "GET", "/web/account", &c, "").await.0, StatusCode::OK);
    let (s, h, _) = call(&e.app, "POST", &g, &c, &format!("csrf={csrf}")).await;
    assert_eq!(
        (s, h["location"].to_str().unwrap()),
        (StatusCode::SEE_OTHER, format!("/login?next={g}").as_str())
    );
    assert_eq!(e.state.db.token_list(&alpha, "bob").unwrap().len(), 1);
    // AUTH-03: SSO account turning ON TOTP on an optional tenant needs a fresh sign-in — checked already in
    // `/2fa/start` so a stale session does not display a QR code that `/2fa/confirm` would immediately invalidate.
    let (cookie, csrf) = bob_signs_in(&e, &ca).await;
    let c = [A, ("cookie", cookie.as_str())];
    e.state.db.exec_for_test(&format!(
        "UPDATE session SET created_at = created_at - {} WHERE user_id = 'bob';",
        crate::web::FRESH_SIGN_IN + 1
    ));
    let (s, h, _) = call(&e.app, "POST", "/web/account/2fa/start", &c, &format!("csrf={csrf}")).await;
    assert_eq!(
        (s, h["location"].to_str().unwrap()),
        (StatusCode::SEE_OTHER, "/login?next=/web/account")
    );
    // And if the session ages between `/2fa/start` and `/2fa/confirm`, `/2fa/confirm` also refuses and asks to sign in.
    let (cookie, csrf) = bob_signs_in(&e, &ca).await;
    let c = [A, ("cookie", cookie.as_str())];
    let (s, _, page) = call(&e.app, "POST", "/web/account/2fa/start", &c, &format!("csrf={csrf}")).await;
    assert!(s == StatusCode::OK && !page.contains("id=\"tf-setup-pw\""), "{page}");
    let secret = crate::auth::totp::setup_secret(&alpha, cookie.split_once('=').unwrap().1);
    let code = format!(
        "{:06}",
        crate::auth::totp::hotp(&secret, crate::auth::totp::step(crate::auth::totp::now()))
    );
    e.state.db.exec_for_test(&format!(
        "UPDATE session SET created_at = created_at - {} WHERE user_id = 'bob';",
        crate::web::FRESH_SIGN_IN + 1
    ));
    let (s, h, _) = call(
        &e.app,
        "POST",
        "/web/account/2fa/confirm",
        &c,
        &format!("csrf={csrf}&code={code}"),
    )
    .await;
    assert_eq!(
        (s, h["location"].to_str().unwrap()),
        (StatusCode::SEE_OTHER, "/login?next=/web/account")
    );
    assert_eq!(e.state.db.totp_get(&alpha, "bob").unwrap(), Some((None, 0)));
    // Fresh sign-in: TOTP setup succeeds.
    let (cookie, csrf) = bob_signs_in(&e, &ca).await;
    let c = [A, ("cookie", cookie.as_str())];
    let secret = crate::auth::totp::setup_secret(&alpha, cookie.split_once('=').unwrap().1);
    let code = format!(
        "{:06}",
        crate::auth::totp::hotp(&secret, crate::auth::totp::step(crate::auth::totp::now()))
    );
    assert_eq!(
        call(
            &e.app,
            "POST",
            "/web/account/2fa/confirm",
            &c,
            &format!("csrf={csrf}&code={code}")
        )
        .await
        .0,
        StatusCode::OK
    );
    // With two-step verification: the code is asked on Login Flow.
    let (cookie, _) = bob_signs_in(&e, &ca).await;
    let (_, _, page) = call(&e.app, "GET", &g, &[A, ("cookie", cookie.as_str())], "").await;
    assert!(
        page.contains("name=\"code\"") && !page.contains("name=\"password\""),
        "{page}"
    );
}
